 for f in v['files'][1:]:
  lines=f['content'].splitlines();mid=next(x[4:] for x in lines if x.startswith('id: '));ver=int(next(x[9:] for x in lines if x.startswith('version: ')));mods.append({'id':mid,'version':ver})
