def finding(report,id,axis,observation,evidence,obligations,*,owner,origin='intrinsic',role='primary',priority='P1',confidence='high',confounds=()):
 fid=report['lane_id']+':'+id
 f={'id':fid,'owner_key':owner,'scale':'regional','axis':axis,'priority':priority,'observation':observation,'source_evidence':evidence,'confidence':confidence,'causal_origin':origin,'materiality':'material','proposed_role':role,'default_drift_risk':'high' if role=='primary' else 'medium','confounders':list(confounds),'atomic_obligations':[]}
 for oid,oaxis,result,direction,regions,kind in obligations:
  f['atomic_obligations'].append({'id':fid+':'+oid,'axis':oaxis,'visible_result':result,'result_direction':direction,'subject_or_region_ids':regions,'relation_kind':kind,'source_evidence':evidence,'confidence':confidence,'causal_origin':origin,'attribution_status':'confounded' if confounds else 'resolved','materiality':'material','proposed_role':role,'target_strength':'moderate','confounders':list(confounds)})
 report['findings'].append(f);return fid

def freeze(report,name,start):
 raw=json.dumps(report,ensure_ascii=False,indent=2)+'\n';Path('output/'+name+'.report.raw.json').write_text(raw);Path('output/'+name+'.report.json').write_text(raw)
 Path('output/'+name+'.report-provenance.json').write_text(json.dumps({'author':'case-02 integrator','context':'sequential-fallback; not independent','analysis_event_start_utc':start,'frozen_utc':now(),'raw_sha256':hashlib.sha256(raw.encode()).hexdigest(),'raw_bytes':len(raw.encode()),'instruction_view':'output/'+report['lane_id']+'-instructions.json','source_inspection':'original pixels inspected in current case context','successful_lane_rerun':False},indent=2))
 print(name,'frozen',len(report['findings']),'findings',sum(len(f['atomic_obligations']) for f in report['findings']),'obligations')

